/* ---------------- einmaliger Export für Cloudflare D1 (nur im Editor ausführen) ---------------- */
// Schreibt alle Tabellen als SQL INSERTs in eine Datei im privaten Ordner Raum Leitung. Keine öffentliche Aktion.
// Jede Zeile der Datei ist eine Anweisung unter 90 KB (D1 Grenze 100 KB). Große Profilbilder werden angehängt.
const D1_BOOL_ = { members: ["active"], songs: ["cello", "gema", "ccli"] };
const D1_NUM_ = { invoices: ["amount"] };
const D1_MAX_ = 90000;
function utf8len_(s) { let n = 0; for (let i = 0; i < s.length; i++) { const c = s.charCodeAt(i); n += c < 0x80 ? 1 : c < 0x800 ? 2 : (c >= 0xD800 && c < 0xDC00) ? (i++, 4) : 3; } return n; }
function d1q_(v) { return "'" + String(v).replace(/'/g, "''") + "'"; }
function d1cell_(tab, col, v) {
  if ((D1_BOOL_[tab] || []).indexOf(col) >= 0) return v === true || v === "TRUE" ? "1" : v === false || v === "FALSE" ? "0" : "NULL";
  if ((D1_NUM_[tab] || []).indexOf(col) >= 0) return v === "" || v === null || v === undefined || isNaN(Number(v)) ? "NULL" : String(Number(v));
  if (v === "" || v === null || v === undefined) return "NULL";
  return d1q_(encode_(v)); // wie im Sheet: true/false als TRUE/FALSE, Objekte als JSON
}
function d1Statements_() {
  const out = [], report = {};
  const tabs = Object.keys(FIELDS);
  tabs.forEach(tab => {
    let rows;
    if (tab === "log") {
      const sh = sheet_("log"); const v = sh ? sh.getDataRange().getValues().slice(1) : [];
      rows = v.filter(r => r[0] !== "").map(r => ({ at: Object.prototype.toString.call(r[0]) === "[object Date]" ? r[0].toISOString() : String(r[0]), by: r[1], action: r[2], entity: r[3], id: r[4], summary: r[5] }));
    } else rows = readAll_(tab);
    report[tab] = rows.length;
    const cols = FIELDS[tab], head = "INSERT INTO \"" + tab + "\" (" + cols.map(c => "\"" + c + "\"").join(",") + ") VALUES ";
    let cur = [], size = utf8len_(head);
    rows.forEach(r => {
      const t = "(" + cols.map(c => d1cell_(tab, c, r[c])).join(",") + ")";
      const n = utf8len_(t) + 1;
      if (cur.length && size + n > D1_MAX_) { out.push(head + cur.join(",") + ";"); cur = []; size = utf8len_(head); }
      if (utf8len_(head) + n > D1_MAX_) throw new Error("Zeile zu groß für D1: " + tab + " " + (r.id || ""));
      cur.push(t); size += n;
    });
    if (cur.length) out.push(head + cur.join(",") + ";");
  });
  // Profilbilder: erst leere Zeile, dann in Stücken anhängen
  const av = sheet_("avatars");
  const ids = av ? av.getDataRange().getValues().slice(1).map(r => String(r[0])).filter((x, i, a) => x && a.indexOf(x) === i) : [];
  ids.forEach(id => {
    const data = loadBigAvatar_(id);
    out.push("INSERT INTO \"avatars\" (\"id\",\"data\") VALUES (" + d1q_(id) + ",'');");
    // 25.000 Zeichen sind höchstens 75 KB; ein Emoji (zwei Zeichen) wird nie geteilt
    for (let p = 0; p < data.length;) {
      let e = Math.min(p + 25000, data.length);
      const c = data.charCodeAt(e - 1); if (e < data.length && c >= 0xD800 && c < 0xDC00) e--;
      out.push("UPDATE \"avatars\" SET \"data\" = \"data\" || " + d1q_(data.slice(p, e)) + " WHERE \"id\" = " + d1q_(id) + ";");
      p = e;
    }
  });
  report.avatars = ids.length;
  return { statements: out, report: report };
}
function exportForD1() {
  const r = d1Statements_();
  const d = new Date(), name = "raumhub-d1-export-" + Utilities.formatDate(d, tz_(), "yyyy-MM-dd") + "-" + Utilities.formatDate(d, tz_(), "HH:mm").replace(":", "") + ".sql";
  const file = DriveApp.getFolderById(P.getProperty("LEITUNG_FOLDER")).createFile(Utilities.newBlob(r.statements.join("\n") + "\n", "text/plain", name));
  const msg = "Export fertig: " + name + " (" + r.statements.length + " Anweisungen). Zeilen: " + JSON.stringify(r.report);
  Logger.log(msg);
  return { file: file.getId(), name: name, statements: r.statements.length, report: r.report };
}

/* ---------------- Daten nach Cloudflare D1 schicken (nur im Editor ausführen) ---------------- */
// Braucht drei Skripteigenschaften, die Oti selbst einträgt: CF_ACCOUNT_ID, CF_D1_DB und CF_API_TOKEN (nur D1 Rechte).
// Bricht ab, wenn die Ziel Datenbank schon Tabellen hat. Nichts wird gelöscht.
function d1SchemaSql_() {
  const out = Object.keys(FIELDS).map(tab => {
    const key = tab === "settings" ? "key" : tab === "log" ? null : "id";
    const cols = FIELDS[tab].map(c => "\"" + c + "\" " + ((D1_NUM_[tab] || []).indexOf(c) >= 0 ? "REAL" : (D1_BOOL_[tab] || []).indexOf(c) >= 0 ? "INTEGER" : "TEXT") + (key === c ? " PRIMARY KEY" : ""));
    if (key === null) cols.unshift("\"seq\" INTEGER PRIMARY KEY");
    if (tab === "members") cols.push("\"last_seen_at\" TEXT");
    return "CREATE TABLE \"" + tab + "\" (" + cols.join(", ") + ");";
  });
  out.push("CREATE TABLE \"avatars\" (\"id\" TEXT PRIMARY KEY, \"data\" TEXT);");
  out.push("CREATE TABLE \"events\" (\"id\" INTEGER PRIMARY KEY, \"at\" TEXT NOT NULL, \"by\" TEXT NOT NULL, \"kind\" TEXT NOT NULL, \"song_id\" TEXT, \"part_key\" TEXT, \"task_id\" TEXT, \"old\" TEXT, \"new\" TEXT, \"summary\" TEXT);");
  out.push("CREATE INDEX \"idx_events_at\" ON \"events\"(\"at\");");
  out.push("CREATE INDEX \"idx_log_at\" ON \"log\"(\"at\");");
  return out;
}
function d1Query_(sql) {
  const acc = P.getProperty("CF_ACCOUNT_ID"), db = P.getProperty("CF_D1_DB"), tok = P.getProperty("CF_API_TOKEN");
  if (!acc || !db || !tok) throw new Error("Skripteigenschaften CF_ACCOUNT_ID, CF_D1_DB und CF_API_TOKEN fehlen.");
  const res = UrlFetchApp.fetch("https://api.cloudflare.com/client/v4/accounts/" + acc + "/d1/database/" + db + "/query", {
    method: "post", contentType: "application/json", headers: { Authorization: "Bearer " + tok },
    payload: JSON.stringify({ sql: sql }), muteHttpExceptions: true });
  let j = null; try { j = JSON.parse(res.getContentText()); } catch (e) {}
  if (res.getResponseCode() !== 200 || !j || !j.success) {
    const why = j && j.errors && j.errors.length ? j.errors.map(e => e.message).join("; ") : ("HTTP " + res.getResponseCode());
    throw new Error("D1 Fehler: " + why + " | Anweisung: " + sql.slice(0, 120));
  }
  return (j.result && j.result[0] && j.result[0].results) || [];
}
function pushToD1() {
  const t = d1Query_("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE '_cf_%' AND name NOT LIKE 'sqlite_%'");
  if (t.length) throw new Error("Abbruch: Die Ziel Datenbank hat schon Tabellen (" + t.map(x => x.name).join(", ") + "). Nichts wurde geändert.");
  d1SchemaSql_().forEach(d1Query_);
  const r = d1Statements_();
  r.statements.forEach(d1Query_);
  const check = {};
  Object.keys(r.report).forEach(tab => { check[tab] = Number(d1Query_("SELECT count(*) AS n FROM \"" + tab + "\"")[0].n); });
  const same = Object.keys(r.report).every(tab => check[tab] === r.report[tab]);
  const msg = (same ? "Umzug in D1 vollständig. " : "ACHTUNG Zahlen weichen ab. ") + "Sheet: " + JSON.stringify(r.report) + " D1: " + JSON.stringify(check);
  Logger.log(msg);
  return { ok: same, sheet: r.report, d1: check, statements: r.statements.length };
}

const STD_PARTS=[["drums","Drums","oti"],["percs","Percs","oti"],["bass","Bass","fini"],["synth","Synth","jeremy"],["egit","E-Gitarren",""],["acoustic","Akustik",""],["piano","Piano",""],["keys","Keys",""],["cello","Cello","suli"]];
function stdParts(o){return STD_PARTS.map(([key,name,owner])=>Object.assign({key,name,owner,status:"open",note:"",ext:false},o[key]||{}))}
function wEnvIds_(env) {
  DRIVE_PROTOKOLLE = String(env.DRIVE_PROTOKOLLE || "");
  try { const q = JSON.parse(env.DRIVE_QUICK || "[]"); DRIVE_QUICK = Array.isArray(q) ? q : []; } catch (e) { DRIVE_QUICK = []; }
}

/* ---------------- Worker Kern: D1 Zeilen <-> Sheet Zeilen, Diff, Schreibanweisungen ---------------- */
const W_TABLES_ = Object.keys(FIELDS).filter(t => t !== "log");
const W_INIT_SQL_ = [
  "CREATE TABLE IF NOT EXISTS \"meta\" (\"k\" TEXT PRIMARY KEY, \"v\" INTEGER)",
  "INSERT OR IGNORE INTO \"meta\" (\"k\",\"v\") VALUES ('ver', 0)",
  "CREATE TABLE IF NOT EXISTS \"cache\" (\"k\" TEXT PRIMARY KEY, \"v\" TEXT, \"exp\" INTEGER)"
];
const W_GUARD_ = "(SELECT \"v\" FROM \"meta\" WHERE \"k\" = 'ver') = ?";
function wPlan_(text) { let a = ""; try { a = String(JSON.parse(text).action || ""); } catch (e) {} return { avatars: a === "setAvatar" || a === "getAvatar" }; }
function wLoadSql_(plan) {
  const q = W_TABLES_.map(t => ({ name: t, sql: "SELECT * FROM \"" + t + "\"" }));
  q.push({ name: "__cache", sql: "SELECT * FROM \"cache\"" }, { name: "__ver", sql: "SELECT \"v\" FROM \"meta\" WHERE \"k\" = 'ver'" });
  if (plan.avatars) q.push({ name: "__avatars", sql: "SELECT * FROM \"avatars\"" });
  return q;
}
function wSnap_(plan, results) { // results: Array von Zeilenlisten, gleiche Reihenfolge wie wLoadSql_
  const q = wLoadSql_(plan), s = { tables: {}, cache: [], ver: 0, avatars: null };
  q.forEach((x, i) => { const rows = results[i] || [];
    if (x.name === "__cache") s.cache = rows; else if (x.name === "__ver") s.ver = Number((rows[0] || {}).v || 0);
    else if (x.name === "__avatars") s.avatars = rows; else s.tables[x.name] = rows; });
  return s;
}
function wToSheet_(tab, col, v) {
  if (v === null || v === undefined) return "";
  if ((D1_BOOL_[tab] || []).indexOf(col) >= 0) return v === 1 || v === true ? "TRUE" : v === 0 || v === false ? "FALSE" : "";
  return String(v);
}
function wToD1_(tab, col, v) {
  if (v === "" || v === null || v === undefined) return null;
  if ((D1_BOOL_[tab] || []).indexOf(col) >= 0) return v === true || v === "TRUE" ? 1 : v === false || v === "FALSE" ? 0 : null;
  if ((D1_NUM_[tab] || []).indexOf(col) >= 0) return isNaN(Number(v)) ? null : Number(v);
  if (typeof v === "object") return JSON.stringify(v);
  if (typeof v === "boolean") return v ? "TRUE" : "FALSE";
  return String(v);
}
function wProcess_(snap, text, env) {
  const sheets = W_TABLES_.map(t => shimSheet_(t, FIELDS[t], (snap.tables[t] || []).map(r => FIELDS[t].map(c => wToSheet_(t, c, r[c])))));
  sheets.push(shimSheet_("log", FIELDS.log, []));
  if (snap.avatars) sheets.push(shimSheet_("avatars", ["id", "part", "data"], snap.avatars.map(r => [String(r.id), "0", String(r.data || "")])));
  const cache = new Map(); snap.cache.forEach(r => { if (Number(r.exp) > Date.now()) cache.set(r.k, { v: r.v, exp: Number(r.exp) }); });
  const cacheOrig = JSON.stringify([...cache]);
  REQ_ = { book: shimBook_(sheets), env: env || {}, cache, ops: [] };
  for (const k in W_DOCS_) delete W_DOCS_[k];
  BOOK_ = null; SHEETS_ = {}; // pro Anfrage frisch
  if (typeof wEnvIds_ === "function") wEnvIds_(env || {}); // öffentliche Fassung: Drive IDs aus Cloudflare Variablen
  const out = doPost({ postData: { contents: text } }).s;
  const st = [], book = REQ_.book;
  // eindeutige Marke dieser Anfrage: nur wenn sie gesetzt werden konnte, greifen die folgenden Anweisungen
  let mark; do { mark = Math.floor(Math.random() * 9e15) + 1; } while (mark === snap.ver);
  // Tabellen: neue oder geänderte Zeilen schreiben, verschwundene löschen
  W_TABLES_.forEach(t => {
    const cols = FIELDS[t], key = cols[0];
    const orig = new Map((snap.tables[t] || []).map(r => [String(r[key]), JSON.stringify(cols.map(c => wToD1_(t, c, wToSheet_(t, c, r[c]))))]));
    const sh = book.getSheetByName(t), rows = sh ? sh._rows : [cols];
    const head = rows[0] || cols, now = new Map();
    rows.slice(1).forEach(r => { const id = String(r[head.indexOf(key)] === undefined ? "" : r[head.indexOf(key)]); if (id) now.set(id, cols.map(c => wToD1_(t, c, r[head.indexOf(c)]))); });
    now.forEach((vals, id) => {
      if (orig.get(id) === JSON.stringify(vals)) return;
      st.push({ sql: "INSERT INTO \"" + t + "\" (" + cols.map(c => "\"" + c + "\"").join(",") + ") SELECT " + cols.map(() => "?").join(",") + " WHERE " + W_GUARD_ +
        " ON CONFLICT(\"" + key + "\") DO UPDATE SET " + cols.slice(1).map(c => "\"" + c + "\" = excluded.\"" + c + "\"").join(", "), params: vals.concat([mark]) });
    });
    orig.forEach((v, id) => { if (!now.has(id)) st.push({ sql: "DELETE FROM \"" + t + "\" WHERE \"" + key + "\" = ? AND " + W_GUARD_, params: [id, mark] }); });
  });
  // Protokoll: nur anhängen
  book.getSheetByName("log")._rows.slice(1).forEach(r => st.push({ sql: "INSERT INTO \"log\" (\"at\",\"by\",\"action\",\"entity\",\"id\",\"summary\") SELECT ?,?,?,?,?,? WHERE " + W_GUARD_, params: r.slice(0, 6).map(x => x === "" ? null : String(x)).concat([mark]) }));
  // Profilbilder: Teile zusammensetzen
  const av = book.getSheetByName("avatars");
  if (av) {
    const merged = new Map(); av._rows.slice(1).filter(r => r[0]).sort((a, b) => Number(a[1]) - Number(b[1])).forEach(r => merged.set(String(r[0]), (merged.get(String(r[0])) || "") + String(r[2])));
    const before = new Map((snap.avatars || []).map(r => [String(r.id), String(r.data || "")]));
    new Set([...merged.keys(), ...before.keys()]).forEach(id => {
      if (merged.get(id) === before.get(id)) return;
      st.push({ sql: "DELETE FROM \"avatars\" WHERE \"id\" = ? AND " + W_GUARD_, params: [id, mark] });
      if (merged.has(id)) st.push({ sql: "INSERT INTO \"avatars\" (\"id\",\"data\") SELECT ?,? WHERE " + W_GUARD_, params: [id, merged.get(id), mark] });
    });
  }
  // Login Sperre (CacheService)
  if (JSON.stringify([...REQ_.cache]) !== cacheOrig) {
    st.push({ sql: "DELETE FROM \"cache\" WHERE " + W_GUARD_, params: [mark] });
    REQ_.cache.forEach((e, k) => st.push({ sql: "INSERT INTO \"cache\" (\"k\",\"v\",\"exp\") SELECT ?,?,? WHERE " + W_GUARD_, params: [k, e.v, e.exp, mark] }));
  }
  if (st.length) st.unshift({ sql: "UPDATE \"meta\" SET \"v\" = ? WHERE \"k\" = 'ver' AND \"v\" = ?", params: [mark, snap.ver] });
  const ops = REQ_.ops;
  REQ_ = null;
  return { out, statements: st, ops };
}
// Platzhalter durch die Ergebnisse von Apps Script ersetzen (in Antwort und Schreibanweisungen)
function wFill_(r, results) {
  const rep = x => typeof x === "string" && x.indexOf("@@RWF") >= 0
    ? x.replace(/@@RWF(\d+)_(id|name|mime|data)@@/g, (m, i, f) => { const v = results[Number(i)]; if (!v || v[f] === undefined) throw new Error("Dateiauftrag ohne Ergebnis"); return String(v[f]); }) : x;
  return { out: rep(r.out), statements: r.statements.map(s => ({ sql: s.sql, params: s.params.map(rep) })), ops: r.ops };
}

/* ---------------- Cloudflare Einstieg ---------------- */
let W_READY_ = false;
async function wFileOps_(env, ops) {
  if (!env.APPS_SCRIPT_URL || !env.FILE_SECRET) throw new Error("Dateidienst ist nicht eingerichtet (APPS_SCRIPT_URL, FILE_SECRET).");
  const res = await fetch(env.APPS_SCRIPT_URL, { method: "POST", headers: { "Content-Type": "text/plain" }, body: JSON.stringify({ action: "fileOps", secret: env.FILE_SECRET, ops }), redirect: "follow" });
  const j = await res.json();
  if (!j.ok) throw new Error("Dateidienst: " + (j.message || j.error));
  return j.data;
}
async function wRun_(env, text) {
  const fileCache = {};
  if (!W_READY_) { await env.DB.batch(W_INIT_SQL_.map(s => env.DB.prepare(s))); W_READY_ = true; }
  for (let i = 0; i < 4; i++) {
    const plan = wPlan_(text), q = wLoadSql_(plan);
    const res = await env.DB.batch(q.map(x => env.DB.prepare(x.sql)));
    let r = wProcess_(wSnap_(plan, res.map(x => x.results)), text, env);
    if (r.ops.length) {
      // nur wenn die Rechnung selbst erfolgreich war (sonst hat sie schon eine Fehlermeldung)
      if (!JSON.parse(r.out).ok) return r.out;
      const key = JSON.stringify(r.ops);
      if (!fileCache[key]) fileCache[key] = await wFileOps_(env, r.ops);
      r = wFill_(r, fileCache[key]);
    }
    if (!r.statements.length) return r.out;
    const done = await env.DB.batch(r.statements.map(s => env.DB.prepare(s.sql).bind(...s.params)));
    if (done[0].meta.changes === 1) return r.out;
  }
  return JSON.stringify({ ok: false, error: "conflict", message: "Gerade ändern viele gleichzeitig. Bitte nochmal versuchen." });
}
export default {
  async fetch(request, env) {
    const origin = request.headers.get("Origin") || "";
    const allowed = String(env.ALLOWED_ORIGINS || "").split(",").map(s => s.trim()).filter(Boolean);
    const cors = { "Access-Control-Allow-Origin": allowed.indexOf(origin) >= 0 ? origin : (allowed[0] || ""), "Access-Control-Allow-Methods": "GET, POST, OPTIONS", "Access-Control-Allow-Headers": "Content-Type", "Vary": "Origin" };
    const send = s => new Response(s, { headers: Object.assign({ "Content-Type": "application/json; charset=utf-8" }, cors) });
    if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: cors });
    if (request.method === "GET") return send(JSON.stringify({ ok: true, data: ACTIONS.ping() }));
    if (request.method !== "POST") return new Response("Method not allowed", { status: 405, headers: cors });
    try { return send(await wRun_(env, await request.text())); }
    catch (e) { return send(JSON.stringify({ ok: false, error: "server", message: "Serverfehler: " + e.message })); }
  }
};
